css:
.card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 190px;
  height: 254px;
  background: #e63946;
  color: #f1faee;
  font-size: 32px;
  font-weight: 700;
  border-radius: 10px;
  cursor: pointer;
  transition: 0.1s 0s linear;
  position: relative;
  overflow: hidden;
}
.card:active {
  scale: 0.95;
}
.card::after {
  content: "";
  width: 500px;
  height: 500px;
  border-radius: 50%;
  background-color: #f1faee;
  position: absolute;
  top: 260px;
  transition: top 0.2s 0s ease-in-out;
  z-index: 1;
}
.card:hover::after {
  top: -50px;
}
.card:hover {
  color: #e63946;
}
.card p {
  position: absolute;
  z-index: 10;
}
